def rattacher_aux_entreprises(apps, schema_editor):
    """Rattache chaque type / code de prix existant à l'entreprise qui l'utilise, quand une
    seule entreprise l'utilise (clients, prix des produits, tournées, plannings). Les autres
    (inutilisés ou utilisés par plusieurs entreprises) restent partagés : rien ne disparaît."""
    Company = apps.get_model('API', 'Company')
    if Company.objects.count() < 2:
        return   # une seule entreprise : les données partagées lui sont déjà visibles
    TypePrix = apps.get_model('API', 'TypePrix')
    CodePrix = apps.get_model('API', 'CodePrix')
    Client = apps.get_model('API', 'Client')
    PrixProduit = apps.get_model('API', 'PrixProduit')
    TourneeMobile = apps.get_model('API', 'TourneeMobile')
    PlanningHebdomadaire = apps.get_model('API', 'PlanningHebdomadaire')

    def entreprises(*listes):
        ids = set()
        for valeurs in listes:
            ids.update(v for v in valeurs if v)
        return ids

    for tp in TypePrix.objects.filter(company__isnull=True):
        ids = entreprises(
            Client.objects.filter(type_prix=tp).values_list('company_id', flat=True).distinct(),
            PrixProduit.objects.filter(type_prix=tp).values_list('produit__company_id', flat=True).distinct())
        if len(ids) == 1:
            TypePrix.objects.filter(pk=tp.pk).update(company_id=ids.pop())

    for cp in CodePrix.objects.filter(company__isnull=True):
        ids = entreprises(
            PrixProduit.objects.filter(code_prix=cp).values_list('produit__company_id', flat=True).distinct(),
            TourneeMobile.objects.filter(code_prix=cp).values_list('company_id', flat=True).distinct(),
            PlanningHebdomadaire.objects.filter(code_prix=cp).values_list('company_id', flat=True).distinct())
        if len(ids) == 1:
            CodePrix.objects.filter(pk=cp.pk).update(company_id=ids.pop())


